INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (1001,2,'Agni Agung Doyan Basmi — Bersifat panas, tidak baik membangun rumah, terutama tidak baik mengatapi rumah, karena mudah terbakar. Baik untuk mulai membakar bata, genteng, gerabah, keramik, tembikar, dan lain-lain. — Anggara Purnama. Anggara Brahma.','referensialaayu');
