INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (1140,2,'Kala Rumpuh — Tidak baik untuk pindah rumah, memulai memelihara ayam, itik, sapi, kerbau, kambing, babi (ternak). — Redite Merakih. Redite Watugunung. Soma Julungwangi. Soma Medangkungan. Buda Sungsang. Buda Tambir. Buda Bala. Buda Ugu. Buda Wayang. Wraspati Langkir. Wraspati Medangsia. Wraspati Krulut. Wraspati Uye. Wraspati Prangbakat. Sukra Dunggulan. Sukra Kuningan. Saniscara Matal. Saniscara Menail. Saniscara Kulawu. Saniscara Dukut.','referensialaayu');
