INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (1144,2,'Kala Sor — Tidak baik untuk bekerja hubungannya dengan dengan tanah seperti membajak, bercocok tanam, membuat terowongan. — Redite Ukir. Redite Julungwangi. Redite Pujut. Redite Matal. Redite Wayang. Soma Sinta. Soma Landep. Soma Warigadean. Soma Gumbreg. Soma Dunggulan. Soma Medangsia. Soma Pahang. Soma Medangkungan. Soma Matal. Soma Ugu. Anggara Sinta. Anggara Kulantir. Anggara Wariga. Anggara Julungwangi. Anggara Langkir. Anggara Medangsia. Anggara Prangbakat. Anggara Bala. Anggara Dukut. Buda Ukir. Buda Warigadean. Buda Kuningan. Buda Langkir. Buda Merakih. Buda Menail. Buda Prangbakat. Buda Kulawu. Buda Watugunung. Wraspati Tolu. Wraspati Dunggulan. Wraspati Krulut. Wraspati Menail. Wraspati Dukut. Sukra Ukir. Sukra Kulantir. Sukra Warigadean. Sukra Sungsang. Sukra Langkir. Sukra Pahang. Sukra Merakih. Sukra Uye. Sukra Menail. Sukra Kulawu. Saniscara Ukir. Saniscara Julungwangi. Saniscara Pujut. Saniscara Matal. Saniscara Wayang.','referensialaayu');
