INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (1212,2,'Taliwangke — Baik untuk memasang tali penghambat di sawah atau di kebun, memperbaiki pagar, membuat tali pengikat padi/benda-benda mati. Tidak baik untuk mulai mengerjakan benang tenun, membuat tali ternak. — Soma Uye. Soma Menail. Soma Prangbakat. Soma Bala. Soma Ugu. Anggara Sinta. Anggara Wayang. Anggara Kulawu. Anggara Dukut. Anggara Watugunung. Buda Landep. Buda Ukir. Buda Kulantir. Buda Gumbreg. Wraspati Wariga. Wraspati Warigadean. Wraspati Julungwangi. Wraspati Sungsang. Wraspati Dunggulan. Wraspati Krulut. Wraspati Merakih. Wraspati Medangkungan. Wraspati Matal. Sukra Kuningan. Sukra Langkir. Sukra Medangsia. Sukra Pujut. Sukra Pahang.','referensialaayu');
INSERT INTO dewasa(id,nama,sifat,deskripsi) VALUES (212,'Taliwangke',NULL,'Baik untuk memasang tali penghambat di sawah atau di kebun, memperbaiki pagar, membuat tali pengikat padi/benda-benda mati. Tidak baik untuk mulai mengerjakan benang tenun, membuat tali ternak.');
