INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (1213,2,'Titibuwuk — Baik untuk menghilangkan penyakit karena guna-guna dan sejenisnya. Tidak baik untuk memulai suatu pekerjaan penting bepergian, membuat tangga/banggul. — Redite Merakih. Redite Ugu. Redite Wayang. Redite Kulawu. Redite Watugunung. Soma Warigadean. Soma Julungwangi. Soma Medangkungan. Anggara Sinta. Anggara Wariga. Anggara Matal. Buda Landep. Buda Kulantir. Buda Tolu. Buda Sungsang. Buda Pujut. Buda Tambir. Buda Bala. Wraspati Gumbreg. Wraspati Langkir. Wraspati Krulut. Wraspati Uye. Wraspati Prangbakat. Sukra Ukir. Sukra Kuningan. Saniscara Pahang. Saniscara Matal. Saniscara Menail. Saniscara Dukut.','referensialaayu');
