INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (1214,2,'Tunut Masih — Baik untuk melas rare (bayi menetek), mulai mengajar/melatih ternak bekerja, membentuk perkumpulan (organisasi), memulai membuka sekolah atau perguruan, baik untuk nelusuk (mencocok hidung sapi atau kerbau) diisi tali pengikat. — Redite Merakih. Soma Julungwangi. Soma Kuningan. Soma Langkir. Soma Wayang. Anggara Krulut. Anggara Prangbakat. Wraspati Sinta. Sukra Tambir. Sukra Uye.','referensialaayu');
